(window.__quranSurahs=window.__quranSurahs||{})[107]={"nomPhon":"Al-Maa'un","versets":{"1":{"text":"Vois-tu celui qui traite de mensonge la Rétribution?","arabe":"أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ"},"2":{"text":"C'est bien lui qui repousse l'orphelin,","arabe":"فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ"},"3":{"text":"et qui n'encourage point à nourrir le pauvre.","arabe":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ"},"4":{"text":"Malheur donc, à ceux qui prient","arabe":"فَوَيْلٌۭ لِّلْمُصَلِّينَ"},"5":{"text":"tout en négligeant (et retardant) leur Salât,","arabe":"ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ"},"6":{"text":"qui sont pleins d'ostentation,","arabe":"ٱلَّذِينَ هُمْ يُرَآءُونَ"},"7":{"text":"et refusent l'ustensile (à celui qui en a besoin).","arabe":"وَيَمْنَعُونَ ٱلْمَاعُونَ"}}};